// V1.3 phase E4a REAL-DATA OPTIONAL GATE. Everything else in this workspace
// validates against synthetic fixtures whose ground truth is wgrib2 reading
// OUR generated bytes. This test replays the Oct 22 2026 live-fire findings
// against PRODUCTION bytes fetched by scripts/fetch_real_sample.sh (MANUAL /
// NETWORK) into tests/realdata/ — a gitignored directory that is NOT
// committed. When the directory is absent (CI, fresh clone) every test here
// prints why and returns Ok: zero network in CI, zero spurious failures.
//
// Pinned expectations (docs/DECISIONS.md §15 diagnosis table):
//   * gfs_sflux_f000/f006/f012: EVERY message rides grid definition template
//     3.40 (3072 x 1536) -> the ONLY skip kind is Grid(40), NOTHING decodes.
//     Correct-by-design within spec §4.3 (only 3.0 + 3.30 mandated); 3.40
//     support is documented as a limitation, not implemented here.
//   * hrrr_apcp_tight.grib2 (212 bytes, zero-window 0-0 day accumulation):
//     decodes successfully as a full-size all-zero plane (wgrib2 parity).
//   * hrrr_tmp2m_f00 / hrrr_uv10m_f06: decode CLEANLY (zero structural
//     skips) and TMP answers at the exact wgrib2 -lon probe nodes recorded
//     on Oct 22 2026 with tools/wgrib2-full:
//       node (lon 264.994145, lat 40.008964) -> 292.957 K
//       node (lon 262.494146, lat 36.986616) -> 295.582 K
//     Wind VALUES are deliberately not pinned here: our store keeps EARTH-
//     relative U/V (spec §4.4 rotation at ingest) while wgrib2 -lon prints
//     the stored grid-relative components (-0.0926971 / 1.68939 at node A,
//     also recorded in DECISIONS); the rotation itself is gated by the
//     fixture-based tests (rotation_vs_pyproj, validate_rotation_wgrib2.sh).
//   * hrrr_windmax_f06.grib2 (WIND 5-6 hour MAX, PDT 4.8): decodes cleanly;
//     its time-interpolation rejection is guarded elsewhere (stat_pdt).

use std::fs;
use std::fs::create_dir_all;
use std::fs::read_dir;
use std::fs::remove_dir;
use std::fs::remove_file;
use std::fs::File;
use std::io::Write;

use wx_core::interp::{PointError, TimeInterpMode};
use wx_ingest::discovery::path_to_str;
use wx_ingest::grib2::{decode_file, ParamFilter};
use wx_ingest::index::{build_context, evaluate_point};
use wx_ingest::pipeline::Pipeline;
use wx_ingest::state::join_path;

const REALDIR: &str = "../../tests/realdata";

fn real_path(name: &str) -> Option<String> {
    let p = format!("{0}/{1}", REALDIR, name);
    let f = File::open(&p);
    match f {
        Err(_) => { return None; }
        Ok(h) => {
            drop(h);
            return Some(p);
        }
    }
}

fn skip_msg(why: &str) {
    println!("SKIP realdata gate: {0} (run scripts/fetch_real_sample.sh to enable)", why);
}

fn rm_tree(dir: &str) {
    match read_dir(&dir) {
        Err(_) => {}
        Ok(it) => {
            for e in it {
                match e {
                    Err(_) => {}
                    Ok(de) => {
                        let p = path_to_str(&de.path());
                        match read_dir(&p) {
                            Err(_) => {
                                let _r = remove_file(&p);
                            }
                            Ok(_) => {
                                rm_tree(&p);
                            }
                        }
                    }
                }
            }
        }
    }
    let _d = remove_dir(&dir);
}

fn copy_in(src: &str, dst: &str) {
    let b = fs::read(src);
    match b {
        Err(_) => { assert!(false); return; }
        Ok(v) => {
            match File::create(dst) {
                Err(_) => { assert!(false); return; }
                Ok(mut w) => {
                    let n = w.write_all(&v);
                    match n { Err(_) => { assert!(false); } Ok(_) => {} }
                }
            }
        }
    }
}

// ---------------------------------------------------------------------------
// GFS sflux family: every skip is Grid(40), nothing else, nothing decoded
// ---------------------------------------------------------------------------

#[test]
fn gfs_sflux_skips_are_grid_40_only() {
    let names = ["gfs_sflux_f000.grib2", "gfs_sflux_f006.grib2", "gfs_sflux_f012.grib2"];
    let mut seen = 0;
    for nm in names.iter() {
        let p = match real_path(nm) {
            None => { continue; }
            Some(x) => { x }
        };
        seen += 1;
        let r = decode_file(p, ParamFilter::All);
        match r {
            Err(e) => {
                println!("{0}: walk failed: {1:?}", nm, e);
                assert!(false);
                return;
            }
            Ok((msgs, st)) => {
                // Honest expectation pinned per DECISIONS §15: the live GFS
                // sflux line is template 3.40 END TO END until E4b-era work
                // adds that template. Any OTHER kind appearing means product
                // drift and must be re-diagnosed, not silently accepted.
                if !(st.messages_total >= 1
                     && msgs.is_empty()
                     && st.messages_decoded == 0
                     && st.skip_coordlists == 0
                     && st.skip_pdt.is_empty()
                     && st.skip_grid.len() == 1
                     && st.skip_grid[0].0 == 40
                     && st.skip_grid[0].1 == st.messages_total) {
                    println!("{0}: total={1} decoded={2} coord={3} grid={4:?} pdt={5:?}",
                             nm, st.messages_total, st.messages_decoded,
                             st.skip_coordlists, st.skip_grid, st.skip_pdt);
                    assert!(false);
                    return;
                }
            }
        }
    }
    if seen == 0 { skip_msg("no gfs_sflux_* files under tests/realdata/"); }
    else { println!("gfs_sflux grid-40-only skips verified for {0} file(s)", seen); }
}

// ---------------------------------------------------------------------------
// The 212-byte zero-window APCP: decodes as a full-size all-zero plane
// ---------------------------------------------------------------------------

#[test]
fn apcp_tight_decodes_as_full_size_zero_plane() {
    let p = match real_path("hrrr_apcp_tight.grib2") {
        None => { skip_msg("hrrr_apcp_tight.grib2 absent"); return; }
        Some(x) => { x }
    };
    let meta = fs::metadata(&p);
    let size = match meta { Err(_) => { assert!(false); return; } Ok(m) => { m.len() } };
    let r = decode_file(p, ParamFilter::All);
    match r {
        Err(e) => {
            println!("APCP tight failed to decode: {0:?}", e);
            assert!(false);
            return;
        }
        Ok((msgs, st)) => {
            assert!(st.messages_unsupported == 0);
            assert!(msgs.len() == 1);
            // LCC 1799 x 1059 from the GRID DEFINITION, never from section 5
            assert!(msgs[0].data.len() == 1905141);
            if size == 212 {
                // exactly the degenerate shape: empty section 7, no bitmap ->
                // constant zero (tools/wgrib2-full parity: mean=min=max=0)
                let mut bad = 0usize;
                for v in &msgs[0].data {
                    if *v != 0.0 { bad += 1; }
                }
                assert!(bad == 0);
            }
        }
    }
}

// ---------------------------------------------------------------------------
// WIND 5-6 hour maximum (PDT 4.8): decodes cleanly on production bytes
// ---------------------------------------------------------------------------

#[test]
fn wind_max_message_decodes_cleanly() {
    let p = match real_path("hrrr_windmax_f06.grib2") {
        None => { skip_msg("hrrr_windmax_f06.grib2 absent"); return; }
        Some(x) => { x }
    };
    let r = decode_file(p, ParamFilter::All);
    match r {
        Err(e) => { println!("WIND max walk failed: {0:?}", e); assert!(false); return; }
        Ok((msgs, st)) => {
            // structurally fine (PDT 4.8 IS supported for decoding); its
            // TIME-INTERPOLATION rejection is the guard tested by stat_pdt
            // and enforced again at query level in wx-server.
            assert!(st.messages_unsupported == 0);
            assert!(st.skip_grid.is_empty());
            assert!(msgs.len() >= 1);
            assert!(msgs[0].data.len() == 1905141);
        }
    }
}

// ---------------------------------------------------------------------------
// HRRR TMP/UV/WIND/APCP: clean ingest + wgrib2 node probes through the index
// ---------------------------------------------------------------------------

fn real_cfg_text(root: &str) -> String {
    let ing = join_path(&root, "ingest");
    let data = join_path(&root, "data");
    let t = "[server]\nbind = \"127.0.0.1:8080\"\ndata_dir = \"";
    let t = format!("{0}{1}", t, data);
    let t = t + "\"\n\n[ingest]\nscan_interval_secs = 30\nretention_runs = 4\nstable_window_secs = 0\n\n[[models]]\nname = \"hrrr\"\ningest_dir = \"";
    let t = format!("{0}{1}", t, ing);
    let t = t + "\"\nfile_glob = \"hrrr_*.grib2\"\n\n  [[models.params]]\n  name = \"TMP\"\n  levels = [\"height_above_ground:2\"]\n\n  [[models.params]]\n  name = \"UGRD\"\n  levels = [\"height_above_ground:10\"]\n\n  [[models.params]]\n  name = \"VGRD\"\n  levels = [\"height_above_ground:10\"]\n\n  [[models.params]]\n  name = \"APCP\"\n  levels = [\"surface\"]\n";
    return t;
}

#[test]
fn hrrr_real_data_ingests_and_matches_wgrib2_probes() {
    let tmpf = match real_path("hrrr_tmp2m_f00.grib2") {
        None => { skip_msg("hrrr_tmp2m_f00.grib2 absent"); return; }
        Some(x) => { x }
    };
    let uvf = real_path("hrrr_uv10m_f06.grib2");
    let apcpf = real_path("hrrr_apcp_tight.grib2");

    let root = "/tmp/opencode/wxpoint-realgate".to_string();
    rm_tree(&root);
    let ing = join_path(&root, "ingest");
    let _c = create_dir_all(&ing);
    copy_in(&tmpf, &join_path(&ing, "hrrr_tmp2m_f00.grib2"));
    let mut nfiles = 1usize;
    match &uvf {
        Some(p) => { copy_in(p, &join_path(&ing, "hrrr_uv10m_f06.grib2")); nfiles += 1; }
        None => {}
    }
    match &apcpf {
        Some(p) => { copy_in(p, &join_path(&ing, "hrrr_apcp_tight.grib2")); nfiles += 1; }
        None => {}
    }
    let cfgp = join_path(&root, "config.toml");
    match File::create(&cfgp) {
        Err(_) => { assert!(false); return; }
        Ok(mut w) => {
            let _n = w.write_all(real_cfg_text(&root).as_bytes());
        }
    }

    let po = Pipeline::open(&cfgp);
    let mut p = match po {
        Err(e) => { println!("open failed: {0}", e); assert!(false); return; }
        Ok(pp) => { pp }
    };
    let _n1 = p.scan_round();
    let n2 = p.scan_round();
    assert!(n2 == nfiles);
    assert!(p.counters.errors == 0);
    assert!(p.counters.ingested_files == nfiles as u64);
    // ZERO structural skips on production HRRR bytes (regression guard that
    // E4a's framing relaxation did not break the happy path).
    assert!(p.counters.skip_coordlists == 0);
    assert!(p.counters.skip_grid == 0);
    assert!(p.counters.skip_pdt == 0);

    let snap = p.shared.get_index();
    let sref = &*snap;
    match sref.find_model("hrrr") {
        None => { assert!(false); return; }
        Some(m) => {
            assert!(m.runs.len() == 1);
            // TMP @ 2 m AGL, forecast hour 0 (anl), exact-node probes
            let cb = build_context(sref, "hrrr", None, "TMP", 103, 2.0, 0.0,
                                   TimeInterpMode::Linear);
            match cb {
                Err(e) => { println!("TMP ctx: {0:?}", e); assert!(false); }
                Ok(c) => {
                    let v1 = evaluate_point(&c, 40.008964, 264.994145);
                    match v1 {
                        Err(other) => { println!("probe A: {0:?}", other); assert!(false); }
                        Ok(pv) => {
                            let mut d = pv.value - 292.957;
                            if d < 0.0 { d = -d; }
                            if !(d < 0.01) {
                                println!("probe A value {0} vs wgrib2 292.957", pv.value);
                                assert!(false);
                            }
                        }
                    }
                    let v2 = evaluate_point(&c, 36.986616, 262.494146);
                    match v2 {
                        Err(other) => { println!("probe B: {0:?}", other); assert!(false); }
                        Ok(pv) => {
                            let mut d = pv.value - 295.582;
                            if d < 0.0 { d = -d; }
                            if !(d < 0.01) {
                                println!("probe B value {0} vs wgrib2 295.582", pv.value);
                                assert!(false);
                            }
                        }
                    }
                }
            }
            // APCP surface fh 0: the degenerate zero-window field answers an
            // EXACT 0.0 through the full index path (not null, not error).
            let ca = build_context(sref, "hrrr", None, "APCP", 1, 0.0, 0.0,
                                   TimeInterpMode::Linear);
            match ca {
                Err(e) => { println!("APCP ctx: {0:?}", e); assert!(false); }
                Ok(c) => {
                    let v = evaluate_point(&c, 36.986616, 262.494146);
                    match v {
                        Err(PointError::MissingData) => {
                            println!("APCP zero plane answered missing_data");
                            assert!(false);
                        }
                        Err(other) => { println!("APCP probe: {0:?}", other); assert!(false); }
                        Ok(pv) => { assert!(pv.value == 0.0); }
                    }
                }
            }
            // UV pair @ 10 m AGL, fh 6 h: earth-relative values are finite
            // and physically sane (raw grid-relative probes live in
            // DECISIONS §15; rotation correctness is fixture-gated).
            if uvf.is_some() {
                let cu = build_context(sref, "hrrr", None, "UGRD", 103, 10.0,
                                       6.0 * 3600.0, TimeInterpMode::Linear);
                match cu {
                    Err(e) => { println!("UGRD ctx: {0:?}", e); assert!(false); }
                    Ok(c) => {
                        let v = evaluate_point(&c, 40.008964, 264.994145);
                        match v {
                            Err(other) => { println!("UV probe: {0:?}", other); assert!(false); }
                            Ok(pv) => {
                                if !(pv.value.is_finite() && pv.value.abs() < 100.0) {
                                    println!("implausible U: {0}", pv.value);
                                    assert!(false);
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    rm_tree(&root);
    println!("realdata HRRR gates exercised ({0} file(s) incl. node probes)", nfiles);
}
